"""Regenerate env/requirements.txt from the CURRENT interpreter.

Run it with the interpreter whose versions you want to record:

    .venv\\Scripts\\python.exe env\\freeze_env.py

It only reads importlib.metadata; it installs and changes nothing.

Note: this overwrites env/requirements.txt, so any hand-written comments in that
file are replaced by a short ASCII header. The Chinese explanation of what each
package is for lives in env/README_ENVIRONMENT.md, which this script never touches.

Console output is ASCII on purpose so it renders under any Windows code page.
"""
import sys
from importlib.metadata import distributions
from pathlib import Path

OUT = Path(__file__).resolve().parent / "requirements.txt"

rows = sorted(f"{d.metadata['Name']}=={d.version}" for d in distributions())
header = [
    "# KDE/LOF course project -- pinned dependencies",
    "# Usage:  pip install -r env/requirements.txt",
    "# Regenerated by env/freeze_env.py; explanation in env/README_ENVIRONMENT.md.",
    f"# Interpreter: {sys.executable}",
    f"# Python: {sys.version.split()[0]}",
    "# If pip cannot find one of these versions for your Python, install",
    "# env/requirements_min.txt instead, then record what you actually got.",
    "",
]
OUT.write_text("\n".join(header + rows) + "\n", encoding="utf-8")
print(f"wrote {OUT} ({len(rows)} packages)")
